// Nested pentagons that twist into a spiral and wobble. Rings drawn around the centre in
// polar coordinates become pentagons once the angle is folded into five equal wedges.
// The wobble comes from sums of sine waves that loop exactly once over iDuration.
#define PI 3.14159265
#define SIDES 5.0

// A pseudo-random number from two inputs.
float rand(float x, float y) {
  return fract(103.2 * sin(5102.2 * x + 983.87 * y + 23.1) * (7.0 * x + 923.2 * y));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;

  // Polar coordinates: x is the angle, y the distance from the centre.
  uv = vec2(atan(uv.x, uv.y), length(uv));
  // Turn the angle more the further out we are, which makes a spiral.
  uv.x += 1.01056 * uv.y;

  // Squiggles: two sets of sine waves around the circle, with random phases, one set
  // drifting forwards and the other backwards three times as fast.
  float t = 2.0 * PI * iTime / iDuration;
  float wobble = 0.0;
  for (float i = 1.0; i <= 64.0; i += 4.0) {
    float amp = 1.0 / (1.0 + 0.01 * i);
    wobble += amp * sin(t + 2.0 * i * (uv.x + PI * rand(i, 1.0) + 0.5 * clamp(uv.y, 0.0, 0.5)));
    wobble += amp * sin(-3.0 * t + 2.0 * i * (uv.x + PI * rand(i, 2.0) - 0.5 * clamp(uv.y, 0.0, 0.5)));
  }
  // Push both the angle and the distance by the wobble, more towards the outside.
  uv += 0.0025 * wobble * clamp(uv.y - 0.1, 0.0, 1.0);

  // Fold the angle into one wedge of the pentagon. Multiplying the distance by cos(angle)
  // turns circles into straight-sided polygons.
  uv.x = mod(uv.x, 2.0 * PI / SIDES) - PI / SIDES;
  uv.y *= cos(uv.x);

  // Black rings on white, leaving a clear patch in the middle.
  float ring = smoothstep(0.0, 0.1, fract(0.5 + 45.0 * uv.y) - 0.7) * step(0.1, uv.y);
  fragColor = vec4(vec3(1.0 - ring), 1.0);
}
